// Category A — React Aria owns the hue wheel behavior and conic track gradient.
import {
  ColorWheel as AriaColorWheel,
  ColorWheelTrack,
  ColorThumb,
} from "react-aria-components";
import type { ColorWheelProps as AriaColorWheelProps } from "react-aria-components";
import { useId, type Ref } from "react";
import "./ColorWheel.css";

export interface ColorWheelProps
  extends Omit<AriaColorWheelProps, "className" | "children" | "outerRadius" | "innerRadius"> {
  /** Outer wheel radius in pixels. */
  outerRadius?: number;
  /** Inner wheel radius in pixels. */
  innerRadius?: number;
  /**
   * Helper text describing the control, wired to its `aria-describedby`.
   *
   * React Aria provides no description slot for any of the three `Color*` controls (in the
   * installed package `ColorSlider.mjs`, `ColorArea.mjs` and `ColorWheel.mjs`
   * mention `description` zero times, where `TagGroup` and `ListBox` hand `descriptionProps` to a
   * `TextContext`), so a `Text` slotted here would render and describe nothing. The id is
   * generated and passed explicitly, the same way `Slider` does it.
   *
   * It goes on the ROOT, not the thumb: `ColorThumb` reads its props from context and does not
   * render the input, so the element carrying the control role is built by the root from React
   * Aria's own hook. (`Slider` is the opposite — there `SliderThumb` renders it, so the id goes on
   * the thumb.) Merged with any
   * `aria-describedby` the consumer passes, rather than replacing it.
   */
  description?: string;
  /** Additional class. sd-color-wheel is always preserved. */
  className?: string;
  /** Passed to the underlying wheel DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ColorWheel({
  outerRadius = 100,
  innerRadius = 74,
  description,
  className,
  ref,
  ...props
}: ColorWheelProps) {
  const descriptionId = useId();
  return (
    <AriaColorWheel
      outerRadius={outerRadius}
      innerRadius={innerRadius}
      {...props}
      aria-describedby={
        [props["aria-describedby"], description ? descriptionId : null].filter(Boolean).join(" ") ||
        undefined
      }
      ref={ref}
      className={className ? `sd-color-wheel ${className}` : "sd-color-wheel"}
    >
      <ColorWheelTrack className="sd-color-wheel__track" />
      <ColorThumb className="sd-color-wheel__thumb" />
      {description && (
        <div id={descriptionId} className="sd-color-wheel__description sd-type-caption-medium">
          {description}
        </div>
      )}
    </AriaColorWheel>
  );
}

.sd-color-wheel {
  flex-shrink: 0;
}
.sd-color-wheel[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-color-wheel__track {
  border-radius: var(--sd-color-wheel-track-radius);
  corner-shape: round;
  forced-color-adjust: none;
}

.sd-color-wheel__thumb {
  width: var(--sd-color-wheel-thumb-size);
  height: var(--sd-color-wheel-thumb-size);
  border: var(--sd-color-wheel-thumb-border-width) solid var(--sd-color-wheel-thumb-border);
  border-radius: var(--sd-color-wheel-thumb-radius);
  corner-shape: round;
  box-shadow: var(--sd-color-wheel-thumb-shadow);
  box-sizing: border-box;
}
/* Hover/drag feedback halo (RAC ColorThumb emits data-hovered/data-dragging), mirrors Slider. */
.sd-color-wheel__thumb[data-hovered] {
  box-shadow: var(--sd-color-wheel-thumb-shadow-hover);
}
.sd-color-wheel__thumb[data-dragging] {
  box-shadow: var(--sd-color-wheel-thumb-shadow-dragging);
}
.sd-color-wheel__thumb[data-focus-visible] {
  width: var(--sd-color-wheel-thumb-size-focused);
  height: var(--sd-color-wheel-thumb-size-focused);
}

.sd-color-wheel__description {
  padding-inline: var(--sd-color-wheel-text-padding-inline);
  color: var(--sd-color-wheel-description-foreground);
}
